function validate([nums]) {
  if (nums.length < 1 || nums.length > 100) return 'nums needs 1 to 100 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v > 1000)) return 'Each value is between 0 and 1000.';
  return null;
}

