function smallestIndex(nums) {
  for (let i = 0; i < nums.length; i++) {
    let value = nums[i];
    let digitSum = 0;
    while (value > 0) {
      digitSum += value % 10;
      value = Math.floor(value / 10);
    }
    if (digitSum === i) {
      return i;
    }
  }
  return -1;
}

