function smallestIndex(nums) {
  // Collect every matching index from the decimal strings, then take the smallest one.
  const matches = [];
  nums.forEach((num, index) => {
    const sum = String(num).split('').reduce((total, digit) => total + Number(digit), 0);
    if (sum === index) matches.push(index);
  });
  return matches.length ? Math.min(...matches) : -1;
}

