function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? 100 : int(1, 12);
  // A random number from 0 to 1000 whose digits add up to target (0 to 27).
  const withDigitSum = target => {
    const hundreds = int(Math.max(0, target - 18), Math.min(9, target));
    const tens = int(Math.max(0, target - hundreds - 9), Math.min(9, target - hundreds));
    return hundreds * 100 + tens * 10 + (target - hundreds - tens);
  };
  const top = [9, 30, 1000][int(0, 2)];
  const nums = Array.from({ length: n }, () => int(0, top));
  // Often plant a match somewhere (it may or may not be the first one).
  if (rand() < 0.6) {
    const at = int(0, Math.min(n - 1, 27));
    nums[at] = withDigitSum(at);
  }
  return [nums];
}
